"""Cold-deploy qualified capacity and restore-consumption fixes after V50."""

import hashlib
import json
from pathlib import Path
import subprocess
import xml.etree.ElementTree as ET


ROOT = Path("/home/longhao/experiment/BeliefKV")
FOLLOWUP = Path("/home/longhao/experiment/.worktrees/beliefkv-v25-followup-20261011")
CHECKOUT = Path("/home/longhao/experiment/.worktrees/beliefkv-v283-v51-headroom-consumption-20261013")
PREVIOUS_CHECKOUT = Path("/home/longhao/experiment/.worktrees/beliefkv-v271-v50-latest-20261013")
PYTHON = "/home/longhao/miniconda3/envs/beliefkv-next/bin/python"
STATE = ROOT / "experiments/reports/v51_launch_after_v50_20261013.json"
LOG = STATE.with_suffix(".log")
PREVIOUS = ROOT / "experiments/raw/qwen35_native_predictive_replenished_108plus48_20261013_v50"
RUN = ROOT / "experiments/raw/qwen35_native_predictive_replenished_108plus48_20261013_v51"
EXPECTED = "0990b73e639bdf7b23e05e24734c168e2d78d2d6"


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


archive = json.loads(
    (FOLLOWUP / "experiments/reports/v281_v50_workspace_archive_20261013.json").read_bytes()
)
if archive["status"] != "verified_and_cleaned" or archive["source_run"] != str(PREVIOUS):
    raise ValueError("V50 archive maintenance incomplete")
if any(path.exists() for path in (STATE, LOG, RUN)):
    raise ValueError("preserve V51 launch state")
revision = subprocess.check_output(
    ["git", "rev-parse", "HEAD"], cwd=CHECKOUT, text=True,
).strip()
if revision != EXPECTED:
    raise ValueError("target is not the qualified committed candidate")
qualification = json.loads(
    (CHECKOUT / "experiments/reports/v277_static_headroom_qualification_20261013.json").read_bytes()
)
for relative, expected in qualification["source_sha256"].items():
    if digest(CHECKOUT / relative) != expected:
        raise ValueError(f"qualified source changed: {relative}")
consumption = json.loads(
    (CHECKOUT / "experiments/reports/v279_restored_consumption_qualification_20261013.json").read_bytes()
)
if digest(CHECKOUT / "beliefkv/runtime/sglang_v0520_runtime.py") != consumption["current_runtime_sha256"]:
    raise ValueError("restored-consumption qualification differs")
if digest(CHECKOUT / "beliefkv/runtime/restore_wait_probe.py") != (
    "00fa8df97010c8fa80e3942e2024a29c235636f1b2760e57dd64bafe07766d0a"
):
    raise ValueError("qualified layer-span probe differs")
for name, tests in (
    ("v277_static_headroom_junit_20261013.xml", 456),
    ("v280_prefill_layer_span_checks_20261013.xml", 110),
):
    suites = ET.parse(CHECKOUT / "experiments/reports" / name).getroot()
    if sum(int(row.get("tests", 0)) for row in suites) != tests or any(
        int(row.get("errors", 0)) or int(row.get("failures", 0)) for row in suites
    ):
        raise ValueError(f"qualification checks incomplete: {name}")
stop = json.loads(
    (FOLLOWUP / "experiments/reports/v281_v50_development_stop_20261013.json").read_bytes()
)
if stop["run_root"] != str(PREVIOUS) or stop["administratively_censored_count"] != 23:
    raise ValueError("unexpected V50 cutoff")
args = [
    PYTHON, str(CHECKOUT / "scripts/launch_semantic_h2d_after_pair.py"),
    "--repo", str(ROOT), "--previous-run", str(PREVIOUS),
    "--previous-checkout", str(PREVIOUS_CHECKOUT),
    "--target-checkout", str(CHECKOUT), "--run-root", str(RUN),
    "--state", str(STATE), "--development-restart", "--port", "18456",
    "--arm-order", "predictive_h2d", "--execution-handoff", "0",
]
for pid in (1904407, 1929309, 1929664, 1931173):
    stat = Path(f"/proc/{pid}/stat")
    if stat.exists() and stat.read_text().rsplit(")", 1)[1].split()[0] != "Z":
        raise ValueError(f"previous PID is still live or reused: {pid}")
    args.extend(("--wait-pid", str(pid)))
with LOG.open("xb") as stream:
    process = subprocess.Popen(
        args, cwd=ROOT, stdout=stream, stderr=subprocess.STDOUT, start_new_session=True,
    )
print(f"coordinator_pid={process.pid}\nstate={STATE}\nlog={LOG}")
